package main

// Tubi detection.
//
// Tubi gives no ad marker in its media session. During an ad it reports state
// PLAYING at speed 1.0 with the title and the position of the show, the same
// as during the show. The log of the capture has no line that marks the ads
// either.
//
// The ad overlay is the marker, as for YouTube. During the show the screen
// capture is blank, apart from a short rating label. During an ad, the
// overlay shows a gray label at the top left, such as "Ad 1 of 3. This ad
// will end in 00:05". The check looks for the fixed words "This ad will end
// in". The numbers before them change, so the words can move to the right.
//
// The label text is near black on a mid gray, so the check uses a lower
// brightness threshold than the YouTube check.
//
// While the show is paused, Tubi can show a still ad with the line "Press any
// button to close the ad". No audio plays then, so ad-mute ignores it: the
// media session reports PAUSED, and the detector captures no screen.

import "image"

const tubiPackage = "com.tubitv"

// tubiAdMask is the words "This ad will end in" from the Tubi ad label, cut
// from a 1920x1080 screen capture. A '#' is a pixel with a luminance above
// 64. The label is gray (128), and the text is near black (6). The top left
// corner of the mask was at x=222, y=92.
var tubiAdMask = []string{
	"#############################################################################################################################################################################################################################################################",
	"#############################################################################################################################################################################################################################################################",
	"########################################....##############################################################################################....#######################################################################################....####################",
	"##.................###....##############....######################################################....####################################....####....####....########################################################....###########....####################",
	"##.................###....##############....######################################################....####################################....####....####....########################################################....###########....####################",
	"##.................###....###############..#######################################################....#####################################..#####....####....########################################################....############..#####################",
	"########.....#########....########################################################################....############################################....####....########################################################....###################################",
	"#########....#########....########################################################################....############################################....####....########################################################....###################################",
	"#########....#########....###....#######....#######......##################.....############...###....##########....#####....######....###....####....####....###############.....########....###....###########...###....###########....####....###....#####",
	"#########....#########....#.......######....#####..........##############.........########.......#....##########....#####.....####.....###....####....####....#############.........######....#.......########.......#....###########....####....#.......####",
	"#########....#########....#........#####....####............############...........######.............##########....#####.....####....####....####....####....############...........#####....#........######.............###########....####....#........###",
	"#########....#########..............####....####....####....###########.....###.....####......##......###########....####.....####....####....####....####....############....###.....####..............####......##......###########....####..............##",
	"#########....#########.....####.....####....####....#####.##############...#####....####....#####.....###########....###......####....####....####....####....###########....######...####.....####.....####....#####.....###########....####.....####.....##",
	"#########....#########....######....####....####....############################....####....######....###########....###......####...#####....####....####....###########...#######....###....######....####....######....###########....####....######....##",
	"#########....#########....######....####....####.......#######################......###.....######....###########....###...#...##....#####....####....####....##########...............###....######....###.....######....###########....####....######....##",
	"#########....#########....######....####....#####..........##############...........###....#######....############...###...#...##....#####....####....####....##########...............###....######....###....#######....###########....####....######....##",
	"#########....#########....######....####....######..........###########.............###....#######....############....#...##...##....#####....####....####....##########...............###....######....###....#######....###########....####....######....##",
	"#########....#########....######....####....##########.......##########....#####....###.....######....############....#...##...##...######....####....####....##########....##############....######....###.....######....###########....####....######....##",
	"#########....#########....######....####....#############....#########....######....####....######....#############...#...###.......######....####....####....###########....#############....######....####....######....###########....####....######....##",
	"#########....#########....######....####....####...######....#########....#####.....####....#####.....#############.......###.......######....####....####....###########....######..#####....######....####....#####.....###########....####....######....##",
	"#########....#########....######....####....####....####.....#########.....####.....####......##......#############......####......#######....####....####....############....####....####....######....####......##......###########....####....######....##",
	"#########....#########....######....####....####............###########.............#####.............##############.....#####.....#######....####....####....############............####....######....#####.............###########....####....######....##",
	"#########....#########....######....####....#####..........############........#....######.......#....##############.....#####.....#######....####....####....#############..........#####....######....######.......#....###########....####....######....##",
	"#########....#########....######....####....#######......################....###....########...###....##############....######.....#######....####....####....###############......#######....######....########...###....###########....####....######....##",
	"#############################################################################################################################################################################################################################################################",
	"#############################################################################################################################################################################################################################################################",
}

// tubiAdText is the words "This ad will end in" and their search area. The
// search area allows the words to move about 220 pixels right, for a longer
// label such as "Ad 10 of 12.", and about 120 pixels left. It also allows a
// move of about 50 pixels up and 100 pixels down. The real ads differ from
// the mask by 0%. Other screens differ by 29% or more.
var tubiAdText = overlayText{
	mask: parseMask(tubiAdMask),
	x0:   100, x1: 450,
	y0: 40, y1: 200,
	threshold:          64,
	maxMismatchPercent: 10,
}

// hasTubiAdLabel reports whether the screen shows the ad label of Tubi.
func hasTubiAdLabel(img image.Image) bool {
	return tubiAdText.on(img)
}
